    res = subprocess.run(['ft2', 'call', tool, json.dumps(kwargs)], capture_output=True, text=True)
    return json.loads(res.stdout)

# Test vibrato 444: effect 4, param 0x44 (68)
call('pattern_set_cell', pattern=0, row=0, channel=0, note='D-4', instrument=1, volume=64, effect=4, effect_param=0x44)
info = json.loads(call('pattern_get_cell', pattern=0, row=0, channel=0)['content'][0]['text'])
print('Vibrato cell:', info)
""}

