import subprocess, json, wave

def call(tool, **kwargs):
    res = subprocess.run(['ft2', 'call', tool, json.dumps(kwargs)], capture_output=True, text=True)
    return json.loads(res.stdout)

for s, e in [(0, 1), (1, 2), (11, 12), (11, 13)]:
    call('module_render', path='test_range.wav', start=s, stop=e)
    with wave.open('test_range.wav', 'rb') as w:
        print(f'start={s}, stop={e} -> frames={w.getnframes()}, dur={w.getnframes()/w.getframerate():.3f}s')
""}

